import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFileSync} from 'node:fs';
import {createGame} from '../engine.js';import {createBootstrapLandscape} from '../game3d/bootstrap-landscape.js';import {createBackgroundQueue} from '../game3d/asset-loading.js';
const sandbox={exports:{},module:{exports:{}},console,setTimeout,clearTimeout,performance,window:{addEventListener(){},removeEventListener(){}},navigator:{userAgent:'node'}};vm.runInNewContext(readFileSync(new URL('../assets/vendor/babylon-9.31.0.js',import.meta.url),'utf8'),sandbox);const B=sandbox.exports.NullEngine?sandbox.exports:sandbox.module.exports;
function fixture(){const s=createGame({start:'established'});s.world.lakes=[{id:'test',cells:[{x:3,y:4}]}];s.buildings=[{type:'canal',x:4,y:4,level:1},{type:'canal',x:5,y:4,level:1}];s.roads=[];s.roadAnchors=[];return s;}
function materials(scene){return Object.fromEntries(['soil','grass','wood','reed','stone'].map(key=>[key,new B.PBRMaterial(`shared-${key}`,scene)]));}
function canal(view,part='water'){return view.meshes.find(m=>m.name===`bootstrap-canal-${part}`);}
function covers(mesh,x,z){const p=mesh.getVerticesData(B.VertexBuffer.PositionKind),indices=mesh.getIndices();for(let j=0;j<indices.length;j+=3){const a=indices.slice(j,j+3).map(i=>[p[i*3],p[i*3+2]]),cross=(p,q)=>(q[0]-p[0])*(z-p[1])-(q[1]-p[1])*(x-p[0]),c=a.map((v,i)=>cross(v,a[(i+1)%3]));if(c.every(v=>v>=-1e-7)||c.every(v=>v<=1e-7))return true;}return false;}
test('saved and newly built canals remain visible while detailed landscape is pending or fails, without state writes',async()=>{
 const engine=new B.NullEngine(),scene=new B.Scene(engine),s=fixture(),shared=materials(scene),view=createBootstrapLandscape(B,scene,s,shared),queue=createBackgroundQueue(1);let fail,swapped=false;
 try{const before=JSON.stringify(s),water=canal(view);assert.ok(water,'saved canal has a lightweight water surface');assert.ok(covers(water,5*6,4*6));const terrain=view.meshes.find(m=>m.name==='alluvial-valley'),ray=new B.Ray(new B.Vector3(5*6,5,4*6),new B.Vector3(0,-1,0));assert.ok(ray.intersectsMesh(terrain).pickedPoint.y<-.18,'terrain is cut beneath the canal water');assert.equal(JSON.stringify(s),before);
  queue.add(()=>new Promise((_resolve,reject)=>fail=reject),()=>swapped=true);await new Promise(resolve=>setTimeout(resolve,0));
  s.buildings.push({type:'canal',x:6,y:4,level:1});const extended=JSON.stringify(s);view.update(s,12);assert.ok(covers(canal(view),6*6,4*6),'canal built during loading is visible');assert.equal(water.isDisposed(),true,'old canal geometry is released on topology change');assert.equal(JSON.stringify(s),extended);
  fail(Error('full landscape unavailable'));await queue.idle();assert.equal(queue.errors.length,1);assert.equal(swapped,false);assert.ok(covers(canal(view),6*6,4*6));assert.ok(view.meshes.every(m=>!m.isDisposed()));assert.equal(JSON.stringify(s),extended);
  s.buildings=s.buildings.filter(b=>b.type!=='canal');const removed=JSON.stringify(s);view.update(s,12);assert.equal(canal(view),undefined);assert.ok(ray.intersectsMesh(terrain).pickedPoint.y>=0,'demolition restores the original terrain');assert.equal(JSON.stringify(s),removed);
 }finally{queue.dispose();view.dispose();for(const m of Object.values(shared))m.dispose();scene.dispose();engine.dispose();}
});
test('disposing the bootstrap at a detail swap releases its canal geometry and private materials only',()=>{
 const engine=new B.NullEngine(),scene=new B.Scene(engine),shared=materials(scene),view=createBootstrapLandscape(B,scene,fixture(),shared);try{const meshes=[...view.meshes],water=canal(view);assert.ok(water);const privateMaterials=scene.materials.filter(m=>!Object.values(shared).includes(m));view.dispose();view.dispose();assert.equal(view.meshes.length,0);assert.ok(meshes.every(m=>m.isDisposed()));assert.ok(privateMaterials.every(m=>!scene.materials.includes(m)));assert.ok(Object.values(shared).every(m=>scene.materials.includes(m)));}finally{view.dispose();for(const m of Object.values(shared))m.dispose();scene.dispose();engine.dispose();}
});
